use serde::{Serialize,Deserialize};
#[derive(Debug,Clone,Copy,Serialize,Deserialize,PartialEq,Eq)] pub struct BackendPass{pub attempted:bool,pub passed:bool}
impl BackendPass{pub fn unavailable()->Self{Self{attempted:false,passed:false}} pub fn passed()->Self{Self{attempted:true,passed:true}}}
#[derive(Debug,Clone,Serialize,Deserialize)] pub struct NativeTernaryPromotionEvidence{pub cpu_canary:BackendPass,pub accelerate_reconstruction:BackendPass,pub metal_packed:BackendPass,pub ane_static:BackendPass,pub cimage_replay:BackendPass,pub behavioral_reference:BackendPass,pub activation_error:f64,pub router_agreement:f64,pub router_margin_error:f64,pub logit_cross_entropy:f64,pub generation_loss:f64,pub expert_balance_error:f64,pub ane_selected:bool,pub packed_abi_digest:String,pub reference_digest:String}
impl NativeTernaryPromotionEvidence{pub fn eligible(&self)->bool{self.reject_reason().is_none()} pub fn reject_reason(&self)->Option<String>{if !self.cpu_canary.passed{Some("CPU canary failed".into())}else if !self.accelerate_reconstruction.passed{Some("Accelerate reconstruction failed".into())}else if !self.metal_packed.passed{Some("Metal packed validation failed".into())}else if !self.cimage_replay.passed{Some("CImage replay failed".into())}else if !self.behavioral_reference.passed{Some("behavioral reference failed".into())}else{None}}}
impl PartialEq for NativeTernaryPromotionEvidence { fn eq(&self, other: &Self) -> bool { self.reference_digest == other.reference_digest && self.packed_abi_digest == other.packed_abi_digest && self.activation_error == other.activation_error && self.generation_loss == other.generation_loss } }
